// Writes testdata/vectors.json: values encrypted by the browser's Secrets
// Manager crypto (apps/web/vault/crypto), which the Go tests must decrypt.
// Run from this directory: node testdata/gen-vectors.mjs
import { writeFileSync } from "node:fs"
import { encryptString } from "../../../apps/web/vault/crypto/enc-string.ts"
import { symmetricKey } from "../../../apps/web/vault/crypto/keys.ts"
import { createAccessToken } from "../../../apps/web/vault/crypto/secrets.ts"

const organizationId = "5c0f4f2a-6f0e-4a8e-9d3b-2f1a7c9e0b11"
const orgKeyBytes = crypto.getRandomValues(new Uint8Array(64))
const orgKey = symmetricKey(orgKeyBytes)
const { token, request } = await createAccessToken(organizationId, orgKey)
const plaintexts = [
  "postgres://prod:s3cr3t@postgres-01:5432/app",
  "sk_live_ünïcode_✓ 日本語 🔐",
  "",
  "x",
  "exactly-sixteen!",
  "line one\nline two\ttabbed",
  "A".repeat(10_000),
]
const secrets = []
for (const plaintext of plaintexts)
  secrets.push({ plaintext, encrypted: await encryptString(plaintext, orgKey) })

writeFileSync(
  new URL("./vectors.json", import.meta.url),
  JSON.stringify(
    {
      note: "Generated by gen-vectors.mjs from the JavaScript crypto; do not edit by hand.",
      organizationId,
      organizationKey: Buffer.from(orgKeyBytes).toString("base64"),
      token,
      encryptedPayload: request.encryptedPayload,
      secrets,
    },
    null,
    2
  ) + "\n"
)
console.log(`wrote ${secrets.length} secrets and a token`)
